            return
        if n < 0:
            self._send(400, b'{"error": "n must be non-negative"}')
            return
        result = fib(n)
        self._send(200, ('{"result": %d}' % result).encode())

    def log_message(self, *args):
        pass


if __name__ == '__main__':
    HTTPServer(('0.0.0.0', 3000), Handler).serve_forever()
